6	export type Item = {
7	  type: string;
8	  material?: string;
9	  enchantment?: number;
10	  cursed?: boolean;
11	};
12	
13	const PROCESSING_FEE = 5;
14	
15	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
16	  sword: 100,
17	  amulet: 60,
18	  staff: 80,
19	  potion: 40,
20	  rune: 25,
21	  moonstone: 25,
22	};
23	
24	const CURSED_SURCHARGE_RATE = 0.5;
25	
26	const basePremiumOf = (item: Item): number => {
27	  const basePremium = BASE_PREMIUM_BY_ITEM_TYPE[item.type];
28	  return item.cursed
29	    ? basePremium + basePremium * CURSED_SURCHARGE_RATE
30	    : basePremium;
31	};
32	
33	const sumBasePremiums = (items: Item[]): number =>
34	  items.reduce((sum, item) => sum + basePremiumOf(item), 0);
35	
36	const BLOCK_SIZE = 3;
37	const BLOCK_BASE_PREMIUM = 60;
38	
39	const isComponentBlock = (sameTypeGroup: Item[]): boolean =>
40	  sameTypeGroup.length === BLOCK_SIZE;
41	
42	const groupByType = (items: Item[]): Item[][] => {
43	  const groups = new Map<string, Item[]>();
44	  for (const item of items) {
45	    const group = groups.get(item.type) ?? [];
46	    group.push(item);
47	    groups.set(item.type, group);
48	  }
49	  return [...groups.values()];
50	};
51	
52	const basePremiumOfGroup = (sameTypeGroup: Item[]): number =>
53	  isComponentBlock(sameTypeGroup)
54	    ? BLOCK_BASE_PREMIUM
55	    : sumBasePremiums(sameTypeGroup);
56	
57	export const quote = (customer: Customer, items: Item[]): number => {
58	  const policyBasePremium = groupByType(items).reduce(
59	    (sum, group) => sum + basePremiumOfGroup(group),
60	    0,
61	  );
62	
63	  return policyBasePremium + PROCESSING_FEE;
64	};
65	
